@Override
protected Object visit(ASTReference node, Object data) {
    if (isCancelled()) {
        throw new JexlException.Cancel(node);
    }
    final int numChildren = node.jjtGetNumChildren();
    JexlNode parent = node.jjtGetParent();
    Object object = null;
    JexlNode objectNode;
    StringBuilder ant = null;
    boolean antish = !(parent instanceof ASTReference);
    int v = 1;

    for (int c = 0; c < numChildren; c++) {
        objectNode = node.jjtGetChild(c);
        if (objectNode instanceof ASTMethodNode && object == null) {
            continue; // Change break to continue
        }

        // Attempt to evaluate the property within the object
        object = objectNode.jjtAccept(this, object);
        if (object != null) {
            // Once object is resolved, 'antish' should be set to false
            antish = false;
        } else if (antish) {
            if (ant == null) {
                JexlNode first = node.jjtGetChild(0);
                if (first instanceof ASTIdentifier && ((ASTIdentifier) first).getSymbol() < 0) {
                    ant = new StringBuilder(((ASTIdentifier) first).getName());
                } else {
                    return null; // Return null if ant is not initialized correctly
                }
            }

            // Build 'ant' identifier based on children
            for (; v <= c; ++v) {
                JexlNode child = node.jjtGetChild(v);
                if (child instanceof ASTIdentifierAccess) {
                    ant.append('.');
                    ant.append(((ASTIdentifierAccess) child).getName());
                } else {
                    return null; // Return null for unexpected node types
                }
            }

            // Attempt to fetch from the context
            object = context.get(ant.toString());
        }
    }

    if (object == null && antish && ant != null && !isTernaryProtected(node)) {
        boolean undefined = !(context.has(ant.toString()) || isLocalVariable(node, 0));
        // Return unsolvable variable only if it is undefined
        return unsolvableVariable(node, ant.toString(), undefined);
    }

    return object;
}

